/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  phases([[0,20],[20,40],[40,56],[56,80]]);
  var s = lin([[2,0],[10,1]]); v.gs = 'opacity: ' + (s * out).toFixed(3) + '; transform: translateY(' + (14 * (1 - s)).toFixed(1) + 'px);';
  var b = lin([[10,0],[16,1]]); v.gb = 'opacity: ' + (b * out).toFixed(3) + ';';
  v.zo = lin([[21,0],[27,1]]) * out; v.zl = lin([[26,0],[30,1]]) * out;
  for (var i = 0; i < 3; i++) v['ty'+i] = p >= 22 + i * 4 ? out : 0.25 * out;
  v.lv = lin([[41,0],[46,1]]) * out;
  var no = 0;
  for (var i = 0; i < 3; i++) { v['hd'+i] = (p >= 57 + i * 4 && p < 59 + i * 4) ? 1 : 0; v['hc'+i] = (p >= 59 + i * 4 && p < 97) ? out : 0; if (p >= 59 + i * 4) no++; }
  v.ol = lin([[66,0],[70,1]]) * out; v.no = no;
  v.fin = (p >= 72 && p < 97) ? out : 0;

  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
export default card;
